-- Lexicon · stage 7: example courses that every teacher can open and copy
-- Run once in Supabase: SQL Editor → New query → paste everything → Run. Safe to run again.
-- Needs stages 3 and 5.

alter table public.courses add column if not exists is_example boolean not null default false;

-- only an admin (or this SQL editor) can turn a course into an example
create or replace function public.courses_example_guard() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null and not public.is_admin() then
    new.is_example := case when tg_op = 'UPDATE' then old.is_example else false end;
  end if;
  return new;
end $$;
drop trigger if exists courses_example_guard on public.courses;
create trigger courses_example_guard before insert or update on public.courses for each row execute function public.courses_example_guard();

-- anyone signed in may read an example course; changing it stays with its owner
drop policy if exists "read courses" on public.courses;
create policy "read courses" on public.courses for select using (is_example or public.can_read_course(teacher_id));

-- the library list now also says which courses are examples
drop function if exists public.my_courses();
create function public.my_courses()
returns table (id uuid, title text, description text, teacher_name text, teacher_email text, mine boolean, topics integer, words integer, updated_at timestamptz, example boolean)
language sql stable security definer set search_path = public as $$
  select c.id, c.title, c.description, coalesce(nullif(t.name, ''), t.email), t.email, c.teacher_id = auth.uid(),
         jsonb_array_length(coalesce(c.data->'topics', '[]'::jsonb)),
         coalesce((select sum(jsonb_array_length(coalesce(tp->'words', '[]'::jsonb)))::int from jsonb_array_elements(coalesce(c.data->'topics', '[]'::jsonb)) tp), 0),
         c.updated_at, c.is_example
  from public.courses c join public.profiles t on t.id = c.teacher_id
  where c.is_example or public.can_read_course(c.teacher_id)
  order by (c.teacher_id = auth.uid()) desc, c.updated_at desc;
$$;
revoke execute on function public.my_courses() from public, anon;
grant execute on function public.my_courses() to authenticated;

